"""URL slugs for titles."""
import re
import unicodedata


def _base_slug(title):
    """Lower-case ASCII words joined by hyphens, or 'untitled' if empty."""
    text = unicodedata.normalize("NFKD", title)
    text = "".join(ch for ch in text if not unicodedata.combining(ch)).lower()
    slug = re.sub(r"[^a-z0-9]+", "-", text).strip("-")
    return slug or "untitled"


def _shorten(slug, limit):
    """Shorten ``slug`` to at most ``limit`` characters using rules 2 to 4.

    Keep the longest run of whole leading words (joined by hyphens) that fits.
    If the first word alone is longer than ``limit``, cut it to ``limit``.
    The result never starts or ends with a hyphen and is never longer than
    ``limit``.
    """
    if len(slug) <= limit:
        return slug
    words = slug.split("-")
    result = ""
    for i, word in enumerate(words):
        candidate = word if i == 0 else result + "-" + word
        if len(candidate) <= limit:
            result = candidate
        else:
            break
    if not result:
        # The first word alone is longer than limit: cut it to exactly limit.
        return words[0][:limit]
    return result


def slugify(title, max_length=None):
    """Turn ``title`` into a URL slug, optionally trimmed to ``max_length``."""
    base = _base_slug(title)
    if max_length is None:
        return base
    if max_length < 1:
        raise ValueError("max_length must be at least 1")
    return _shorten(base, max_length)


def unique_slug(title, taken, max_length=None):
    """Return a slug for ``title`` that is not already in ``taken``.

    ``taken`` is any collection of slugs in use; it is not changed.
    """
    if max_length is not None and max_length < 1:
        raise ValueError("max_length must be at least 1")

    base = slugify(title, max_length)
    if base not in taken:
        return base

    n = 2
    while True:
        suffix = "-" + str(n)
        if max_length is None:
            candidate = base + suffix
        else:
            limit = max_length - len(suffix)
            if limit < 1:
                raise ValueError(
                    "no room for the base slug under max_length"
                )
            candidate = _shorten(base, limit) + suffix
        if candidate not in taken:
            return candidate
        n += 1
